import Atomics

let counter = ManagedAtomic<Int>(0)
counter.wrappingIncrement(ordering: .relaxed)   // relaxed: a counter publishes nothing

// Swift 6 strict concurrency: non-Sendable cannot cross an isolation boundary,
// so the data races this pattern's tradeoffs describe are compile errors
actor Store {
    private var state: [String: Int] = [:]
    func bump(_ key: String) { state[key, default: 0] += 1 }   // isolated: no other task sees it mid-update
}

